package com.alex.universaltoolsapi.screwdriver.api;
import net.minecraft.core.registries.Registries; import net.minecraft.resources.Identifier; import net.minecraft.tags.TagKey; import net.minecraft.world.item.Item; import net.minecraft.world.item.ItemStack; import java.util.*; import java.util.concurrent.*;
public final class ScrewdriverApi { public static final TagKey<Item> SCREWDRIVERS=TagKey.create(Registries.ITEM,Identifier.fromNamespaceAndPath("universal-screwdriver-api","screwdrivers")); private static final List<ScrewdriverHandler> HANDLERS=new CopyOnWriteArrayList<>(); private static final Set<Item> ITEMS=ConcurrentHashMap.newKeySet(); private static final Map<ScrewdriverHookType,List<ScrewdriverHook>> HOOKS=new EnumMap<>(ScrewdriverHookType.class); static{for(var t:ScrewdriverHookType.values())HOOKS.put(t,new CopyOnWriteArrayList<>());} private ScrewdriverApi(){}
public static void registerHandler(ScrewdriverHandler h){HANDLERS.add(Objects.requireNonNull(h));} public static boolean unregisterHandler(ScrewdriverHandler h){return HANDLERS.remove(h);} public static void registerScrewdriver(Item i){ITEMS.add(Objects.requireNonNull(i));} public static boolean unregisterScrewdriver(Item i){return ITEMS.remove(i);} public static boolean isScrewdriver(ItemStack s){return s.is(SCREWDRIVERS)||ITEMS.contains(s.getItem());} public static Set<Item> registeredItems(){return Set.copyOf(ITEMS);}
public static void registerHook(ScrewdriverHookType t,ScrewdriverHook h){HOOKS.get(t).add(Objects.requireNonNull(h));} public static boolean unregisterHook(ScrewdriverHookType t,ScrewdriverHook h){return HOOKS.get(t).remove(h);} public static ScrewdriverActionResult fireHook(ScrewdriverHookType t,ScrewdriverContext c,ScrewdriverActionResult r){for(var h:HOOKS.get(t)){r=h.apply(c,r);if(r==ScrewdriverActionResult.FAIL)break;}return r;}
public static ScrewdriverActionResult invoke(ScrewdriverContext c){var r=fireHook(ScrewdriverHookType.BEFORE_HANDLER,c,ScrewdriverActionResult.PASS);if(r!=ScrewdriverActionResult.PASS)return r;for(var h:HANDLERS){r=h.use(c);if(r!=ScrewdriverActionResult.PASS)break;}return fireHook(ScrewdriverHookType.AFTER_HANDLER,c,r);} }